// A pretend LLM gateway: counts tokens and dollars for two agents, one call per second.
// GET /break makes Nova's prompt cache stop working, GET /fix repairs it.
import { createServer } from "node:http";

const PRICE = { input: 5, cache_read: 0.5 }; // lab dollars per million tokens
const tokens = {};
const cost = { nova: 0, cifix: 0 };
let broken = false;

const add = (agent, type, n) => {
  const key = `${agent}|${type}`;
  tokens[key] = (tokens[key] ?? 0) + n;
  cost[agent] += (n * PRICE[type]) / 1_000_000;
};

setInterval(() => {
  add("nova", "input", broken ? 1700 : 200);
  add("nova", "cache_read", broken ? 300 : 1800);
  add("cifix", "input", 100);
  add("cifix", "cache_read", 900);
}, 1000);

const metrics = () => [
  "# TYPE ai_agents_llm_tokens_total counter",
  ...Object.entries(tokens).map(([k, v]) => {
    const [agent, type] = k.split("|");
    return `ai_agents_llm_tokens_total{agent="${agent}",type="${type}"} ${v}`;
  }),
  "# TYPE ai_agents_llm_cost_usd_total counter",
  ...Object.entries(cost).map(([agent, v]) => `ai_agents_llm_cost_usd_total{agent="${agent}"} ${v}`),
].join("\n") + "\n";

createServer((req, res) => {
  if (req.url === "/break") broken = true;
  if (req.url === "/fix") broken = false;
  if (req.url === "/metrics") return res.end(metrics());
  res.end(`nova prompt cache: ${broken ? "BROKEN" : "working"}\n`);
}).listen(9464, () => console.log("fake gateway on http://localhost:9464/metrics"));
EOF
cat > fake-slack.mjs <<'EOF'
// Stands in for Slack: prints every message Alertmanager sends to its webhook.
import { createServer } from "node:http";

createServer(async (req, res) => {
  let body = "";
  for await (const chunk of req) body += chunk;
  const { status, alerts } = JSON.parse(body);
  for (const a of alerts) console.log(`#ai-agents-alerts  [${status.toUpperCase()}] ${a.annotations.summary}`);
  res.end();
}).listen(5001, () => console.log("fake Slack on http://localhost:5001"));
EOF
